using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PhysicsCollisionWorldOperations:RefCounted
{
    private static Settings Map(RefCounted owner,string key)=>owner.Get(key).AsGodotDictionary();private static Rid Space(RefCounted owner)=>owner.Get("space").AsRid();private static Variant Get(Settings data,Variant key,Variant fallback=default)=>data.TryGetValue(key,out var value)?value:fallback;
    public void remove(RefCounted owner,string id){var bodies=Map(owner,"bodies");if(!bodies.ContainsKey(id))return;var rid=bodies[id].AsGodotDictionary()["rid"].AsRid();Map(owner,"owners").Remove(rid);PhysicsServer3D.FreeRid(rid);bodies.Remove(id);}
    public void reset(RefCounted owner){foreach(var value in Map(owner,"bodies").Values)PhysicsServer3D.FreeRid(value.AsGodotDictionary()["rid"].AsRid());Map(owner,"bodies").Clear();Map(owner,"owners").Clear();var space=Space(owner);if(space.IsValid)PhysicsServer3D.FreeRid(space);owner.Set("space",new Rid());}
    public void create(RefCounted owner){reset(owner);var space=PhysicsServer3D.SpaceCreate();owner.Set("space",space);PhysicsServer3D.SpaceSetActive(space,false);}
    public void add(RefCounted owner,string id,Shape3D shape,Transform3D offset,int layer,int mask){if(!Space(owner).IsValid)create(owner);var rid=PhysicsServer3D.BodyCreate();PhysicsServer3D.BodySetMode(rid,PhysicsServer3D.BodyMode.Static);PhysicsServer3D.BodySetSpace(rid,Space(owner));PhysicsServer3D.BodyAddShape(rid,shape.GetRid(),offset);PhysicsServer3D.BodySetCollisionLayer(rid,unchecked((uint)layer));PhysicsServer3D.BodySetCollisionMask(rid,unchecked((uint)mask));Map(owner,"bodies")[id]=new Settings{["rid"]=rid,["shape"]=shape,["offset"]=offset};Map(owner,"owners")[rid]=id;}
    public void add_compound(RefCounted owner,string id,GArray shapes,int layer,int mask){if(shapes.Count==0){add(owner,id,new SphereShape3D{Radius=.0001f},Transform3D.Identity,0,0);return;}var first=shapes[0].AsGodotDictionary();add(owner,id,first["shape"].As<Shape3D>(),first["offset"].AsTransform3D(),layer,mask);var entry=Map(owner,"bodies")[id].AsGodotDictionary();entry["compound"]=shapes;for(int i=1;i<shapes.Count;i++){var item=shapes[i].AsGodotDictionary();PhysicsServer3D.BodyAddShape(entry["rid"].AsRid(),item["shape"].As<Shape3D>().GetRid(),item["offset"].AsTransform3D());}}
    public void place(RefCounted owner,string id,Transform3D transform,bool enabled){var bodies=Map(owner,"bodies");if(!bodies.ContainsKey(id))return;var body=bodies[id].AsGodotDictionary();body["pose"]=transform;body["enabled"]=enabled;var scale=transform.Basis.Scale.Abs().Max(Vector3.One*.0001f);var scaling=new Transform3D(Basis.FromScale(scale),Vector3.Zero);var rid=body["rid"].AsRid();PhysicsServer3D.BodySetShapeTransform(rid,0,scaling*body["offset"].AsTransform3D());if(body.ContainsKey("compound")){var shapes=body["compound"].AsGodotArray();for(int i=0;i<shapes.Count;i++){PhysicsServer3D.BodySetShapeTransform(rid,i,scaling*shapes[i].AsGodotDictionary()["offset"].AsTransform3D());PhysicsServer3D.BodySetShapeDisabled(rid,i,!enabled);}}PhysicsServer3D.BodySetState(rid,PhysicsServer3D.BodyState.Transform,new Transform3D(transform.Basis.Orthonormalized(),transform.Origin));PhysicsServer3D.BodySetShapeDisabled(rid,0,!enabled);}
    public Settings move(RefCounted owner,string id,Transform3D from,Vector3 motion,GArray exclude){var bodies=Map(owner,"bodies");if(!bodies.ContainsKey(id))return new Settings{["travel"]=motion,["hits"]=new GArray()};var excluded=new Godot.Collections.Array<Rid>();foreach(var other in exclude)if(bodies.ContainsKey(other))excluded.Add(bodies[other].AsGodotDictionary()["rid"].AsRid());var parameters=new PhysicsTestMotionParameters3D{From=new Transform3D(from.Basis.Orthonormalized(),from.Origin),Motion=motion.IsZeroApprox()?Vector3.Down*.0001f:motion,Margin=.002f,MaxCollisions=4,RecoveryAsCollision=true,ExcludeBodies=excluded};var result=new PhysicsTestMotionResult3D();owner.Set("query_count",owner.Get("query_count").AsInt64()+1);if(!PhysicsServer3D.BodyTestMotion(bodies[id].AsGodotDictionary()["rid"].AsRid(),parameters,result))return new Settings{["travel"]=motion,["hits"]=new GArray()};var hits=new GArray();for(int i=0;i<result.GetCollisionCount();i++)hits.Add(new Settings{["normal"]=result.GetCollisionNormal(i),["point"]=result.GetCollisionPoint(i),["depth"]=result.GetCollisionDepth(i),["actor"]=Get(Map(owner,"owners"),result.GetColliderRid(i),"")});return new Settings{["travel"]=result.GetTravel(),["hits"]=hits};}
    public Settings point_motion(RefCounted owner,string id,Vector3 from,Vector3 to,double radius,int layer,int mask,GArray exclude)
    {
        string probe="@probe:"+mask;var bodies=Map(owner,"bodies");if(!bodies.ContainsKey(probe))add(owner,probe,new SphereShape3D{Radius=(float)Math.Max(.0001,radius)},Transform3D.Identity,0,mask);else{var shape=bodies[probe].AsGodotDictionary()["shape"].As<SphereShape3D>();if(!Mathf.IsEqualApprox(shape.Radius,radius))shape.Radius=(float)Math.Max(.0001,radius);}var ignored=exclude.Duplicate();ignored.Add(id);var result=move(owner,probe,new Transform3D(Basis.Identity,from),to-from,ignored);var hits=result["hits"].AsGodotArray();if(from.IsEqualApprox(to)&&hits.Count==0){var body=bodies[probe].AsGodotDictionary();var excluded=new Godot.Collections.Array<Rid>{body["rid"].AsRid()};foreach(var other in ignored)if(bodies.ContainsKey(other))excluded.Add(bodies[other].AsGodotDictionary()["rid"].AsRid());var query=new PhysicsShapeQueryParameters3D{Shape=body["shape"].As<Shape3D>(),Transform=new Transform3D(Basis.Identity,from),CollisionMask=unchecked((uint)mask),Margin=.001f,Exclude=excluded};var info=PhysicsServer3D.SpaceGetDirectState(Space(owner)).GetRestInfo(query);owner.Set("query_count",owner.Get("query_count").AsInt64()+1);if(info.Count>0){var normal=info["normal"].AsVector3();double depth=Math.Max(.001,radius-(from-info["point"].AsVector3()).Dot(normal));hits.Add(new Settings{["normal"]=normal,["point"]=info["point"],["depth"]=depth,["actor"]=Get(Map(owner,"owners"),info["rid"],"")});result["travel"]=normal*(float)Math.Min(depth,radius*2);}}return new Settings{["position"]=from+result["travel"].AsVector3(),["hits"]=hits};
    }
}
